insert into public.confessions (id, user_id, content, is_anonymous, category, mood_tag, like_count, comment_count, moderation_status, created_at) values
  ('c9fd7030-2bc8-4fd0-859e-9d2aeed237be', (select id from public.profiles order by random() limit 1), '23 yaşındayım, evleneli 2 yıl oldu. Eşim bana karşı eskisi gibi değil; ne sarılıyor ne ilgi gösteriyor. Yanına yaklaşınca hep yorgun olduğunu söylüyor. Başta kendimde kusur aradım ama artık gururuma dokunuyor. Susmak mı doğru yoksa konuşmak mı, gerçekten bilmiyorum.', true, 'Aşk', 'Aşk', 851, 4, 'approved', now() - interval '8054 minutes'),
  ('745dfa4c-774e-4c87-8cdc-2edcf839435e', (select id from public.profiles order by random() limit 1), 'Evlendiğimden beri kaynanam bana göz açtırmadı; yemeğimi de evimi de beğenmezdi. Geçen ay hastalanıp yatağa düştü, şimdi her şeyi benden istiyor. Kötülük yapmıyorum, bakıyorum ama içimden bak şimdi muhtaç oldun demekten kendimi alamıyorum. Kötü biri miyim?', true, 'Aile', 'Aile', 72, 6, 'approved', now() - interval '6545 minutes'),
  ('67c9e60b-ac9c-4ead-a2fc-117a532e4cf9', (select id from public.profiles order by random() limit 1), 'Düğünümde takılan bilezikleri eşimden gizli bozdurdum, parayı bir borcu kapatmak için kullandım. Yerine birebir benzeyen imitasyon koydum. Şimdi eşim altınları bozduralım diye tutturdu. Kasayı açarsa her şey ortaya çıkacak. Çok sıkıştım, ne yapacağımı bilmiyorum.', true, 'Aldatma', 'Aldatma', 412, 4, 'approved', now() - interval '19812 minutes'),
  ('3d4fd5ec-95d0-4334-befa-4fadeb18a9ac', (select id from public.profiles order by random() limit 1), 'Eşim son zamanlarda bana sürekli değişiklik yapalım diye baskı kuruyor, istemediğim şeylere zorluyor. Olmaz, yoruldum dedikçe herkes böyle yapıyor, beni sevmiyorsun diye suçluyor. Psikolojik olarak bittim, kendimi değersiz hissediyorum. Bu normal mi?', true, 'Dram', 'Dram', 116, 2, 'approved', now() - interval '21698 minutes'),
  ('4c37eb16-e2e0-4fca-ae9c-0c47068235b7', (select id from public.profiles order by random() limit 1), 'Üniversitede en yakın arkadaşımın sevgilisine âşık oldum ve bir gece çizgiyi aştık. O ilişkiden ayrıldılar ama gerçeği asla öğrenmedi. Yıllar geçti, hâlâ her gördüğümde içim cız ediyor. Bu sırrı mezara mı götürmeliyim?', true, 'Pişmanlık', 'Pişmanlık', 695, 4, 'approved', now() - interval '5359 minutes'),
  ('e57d05ad-3fbf-447a-85bb-b208a3aeec2f', (select id from public.profiles order by random() limit 1), 'Babam ben küçükken başka bir kadına kaçmış, annem beni tek başına büyüttü. Geçen hafta babam aradı, hastayım yanımda kimse yok dedi. Annem gitme diyor ama içimde bir his var. Gitsem anneme ihanet, gitmesem vicdanım rahat etmeyecek.', true, 'Aile', 'Aile', 321, 6, 'approved', now() - interval '7226 minutes'),
  ('2086317d-9c5b-4930-a093-7b791c53a2ae', (select id from public.profiles order by random() limit 1), 'Eşim iş gezisindeyken telefonuna gelen mesajı yanlışlıkla gördüm. Bir kadınla aylardır yazışıyormuş. Hiçbir şey belli etmedim, sanki bilmiyormuşum gibi davranıyorum çünkü kanıt topluyorum. Ona güvenen ben miyim gerçekten, kendime kızıyorum.', true, 'Aldatma', 'Aldatma', 619, 6, 'approved', now() - interval '8639 minutes'),
  ('057c4156-6a10-4586-afe0-ae78a49c6a74', (select id from public.profiles order by random() limit 1), 'İş yerinde herkesin gözünde çok dürüst biriyim. Ama geçen ay kasadan eksilen parayı stajyerin üstüne yıktım, kovuldu. O para bende. Her gün o çocuğun yüzü gözümün önüne geliyor. Geri itiraf etsem işimi kaybederim, etmesem uyuyamıyorum.', true, 'Utanç', 'Utanç', 4667, 4, 'approved', now() - interval '18158 minutes'),
  ('62f364b9-342d-4c56-b282-3d5a93c73381', (select id from public.profiles order by random() limit 1), 'Kız kardeşim hastalandı, tedavi için tüm birikimimi verdim. Şimdi kendi düğünüm için param yok ve nişanlımın ailesi bu yüzden bana yukarıdan bakıyor. Pişman değilim ama bazen ya iyileşmezse diye düşünüp kendimden utanıyorum.', true, 'Dram', 'Dram', 5620, 3, 'approved', now() - interval '16665 minutes'),
  ('6ee35d24-d411-487e-94f2-26483e409833', (select id from public.profiles order by random() limit 1), '10 yıldır evliyim ve kocamı hâlâ ilk günkü gibi seviyorum. Ama o son bir yıldır bana abla gibi davranıyor. Geçen gün doğum günümü unuttu. İnternette bana ilgi gösteren biri var ve ona yazmamak için kendimi zor tutuyorum. Korkuyorum kendimden.', true, 'Aşk', 'Aşk', 64, 2, 'approved', now() - interval '11924 minutes'),
  ('07e49a1c-07b2-4778-8dd7-fac1b01edc7b', (select id from public.profiles order by random() limit 1), 'Her gece aynı rüyayı görüyorum: eşim arabayla bir uçuruma gidiyor ve ben durduramıyorum. Sabah uyandığımda kalbim küt küt atıyor. Ona söyleyemiyorum, deli sanır. Ama bu rüya gerçek olacakmış gibi bir his var içimde, ne yapmalıyım?', true, 'Korku', 'Korku', 542, 2, 'approved', now() - interval '17485 minutes'),
  ('ca9446f4-9216-49b4-90f5-4d47786c617c', (select id from public.profiles order by random() limit 1), 'Müdürüm sürekli benim fikirlerimi kendi fikriymiş gibi yönetime sunuyor, terfiyi de o alıyor. İki yıldır sesimi çıkarmadım. Geçen hafta önemli bir hatasını fark ettim ama düzeltmedim, bilerek. Şimdi büyük bir kriz patladı. İçten içe seviniyorum ama bu beni kötü biri yapar mı?', true, 'İş Hayatı', 'İş Hayatı', 261, 6, 'approved', now() - interval '22635 minutes'),
  ('de2ceb87-1327-4941-8764-f375dff137ed', (select id from public.profiles order by random() limit 1), 'Lisede en çok güvendiğim öğretmenime kopya çektiğimi itiraf etmiştim. O da aramızda kalsın demişti. Yıllar sonra öğrendim ki bunu başka öğretmenlere anlatmış, benimle dalga geçmişler. O günden beri kimseye güvenemiyorum.', true, 'Okul', 'Okul', 117, 2, 'approved', now() - interval '7531 minutes'),
  ('4c38f63a-746e-45d1-af3e-1cfac64bc82e', (select id from public.profiles order by random() limit 1), 'Nişanlım çok kıskanç diye eski fotoğraflarımı, mesajlarımı sildim, hatta bazı arkadaşlarımdan uzaklaştım. Şimdi düğüne 3 ay kala fark ettim ki kendimi kaybetmişim. Onu seviyorum ama eski beni de özlüyorum. Evlenince düzelir mi, yoksa kaçmalı mıyım?', true, 'Aldatma', 'Aldatma', 730, 5, 'approved', now() - interval '7050 minutes'),
  ('8a479d0c-4cad-4062-956e-3a0fdc33112d', (select id from public.profiles order by random() limit 1), 'Annem her telefonda kardeşin şöyle başarılı sen ne yaptın diyor. Çocukken de hep onu överdi. Geçen gün kardeşim borç istedi, param vardı ama yok dedim. İlk defa içim rahatladı, sonra da kendimden tiksindim. Bu kin normal mi?', true, 'Aile', 'Aile', 2123, 2, 'approved', now() - interval '2016 minutes'),
  ('e3b706b1-d754-406a-b394-80845e293854', (select id from public.profiles order by random() limit 1), 'Gençken sırf inat olsun diye sevdiğim adamla evlenmedim, ailem istemiyordu. Şimdi kırkımdayım, yalnızım. Geçen onu bir markette gördüm, mutlu bir ailesi vardı. Eve gelip saatlerce ağladım. Keşke o gün biraz daha cesur olsaymışım.', true, 'Pişmanlık', 'Pişmanlık', 504, 3, 'approved', now() - interval '13854 minutes'),
  ('fff2b9b3-e00d-48c7-ab9b-fe0a0593b1c7', (select id from public.profiles order by random() limit 1), 'Eşimle para yüzünden her gün kavga ediyoruz. Geçen gün çocuğumuz keşke ayrılsanız dedi. O cümle kalbime saplandı. İkimiz de inatçıyız, kimse pes etmiyor. Çocuğum için katlanıyorum ama bu ona iyi mi geliyor kötü mü, artık emin değilim.', true, 'Dram', 'Dram', 1907, 2, 'approved', now() - interval '3086 minutes'),
  ('62d6f767-7c55-4d6a-9f1f-df82bb1a6022', (select id from public.profiles order by random() limit 1), 'Arkadaşımın düğününde takı merasiminde takmam gereken parayı takamadım çünkü o ay çok zordaydım. Herkesin içinde mahcup oldum, bahane uydurdum. O günden beri arkadaşımla aram bozuk. Gururum mu engel oldu, yoksa gerçekten çaresiz miydim, hâlâ düşünüyorum.', true, 'Utanç', 'Utanç', 2740, 3, 'approved', now() - interval '12448 minutes'),
  ('17087b81-d1d3-4096-91b2-60c91e5a981e', (select id from public.profiles order by random() limit 1), 'Kocam çok iyi bir insan, beni el üstünde tutuyor. Ama ben hâlâ üniversiteden eski sevgilimi unutamadım. Sosyal medyada onu gizli gizli takip ediyorum. Kocama haksızlık ettiğimi biliyorum ama kalbim bir türlü buradan kopmuyor. Berbat biri miyim?', true, 'Aşk', 'Aşk', 348, 3, 'approved', now() - interval '1946 minutes'),
  ('ca68cbb5-c861-470c-bf77-bd2e1816f7bc', (select id from public.profiles order by random() limit 1), 'Komşumuzun evinden geceleri garip sesler geliyor, bir kadının ağladığını duyuyorum. Adam çok sinirli biri. Müdahale etsem belki başımı belaya sokarım, etmesem vicdanım sızlıyor. Polise mi haber vermeliyim yoksa karışmamalı mıyım?', true, 'Korku', 'Korku', 565, 2, 'approved', now() - interval '6119 minutes'),
  ('d45e3126-fd1a-4165-bf1a-829354a3493c', (select id from public.profiles order by random() limit 1), 'Yıllardır çalıştığım şirkette en sadık çalışan benim. Geçen ay rakip firma çok iyi bir teklif verdi ama şirketin gizli müşteri listesini de istiyorlar. Param için gözüm karardı, neredeyse kabul ediyordum. Vazgeçtim ama o teklifi hâlâ düşünüyorum, kendimden korkuyorum.', true, 'İş Hayatı', 'İş Hayatı', 881, 6, 'approved', now() - interval '2716 minutes'),
  ('3695d574-40b7-4aed-a2de-4cb5d7d99435', (select id from public.profiles order by random() limit 1), 'Eşim hamileyken ben bir hata yaptım, başka biriyle birlikte oldum. O kişiyle her şey bitti, eşim hiç öğrenmedi. Şimdi kızımız beş yaşında ve ben her gün bu suçlulukla yaşıyorum. İtiraf etsem ailem dağılır, etmesem içim kararıyor.', true, 'Aldatma', 'Aldatma', 2909, 2, 'approved', now() - interval '17647 minutes'),
  ('ef43dbfd-fa5b-45ab-99d3-c24a0e13ab2e', (select id from public.profiles order by random() limit 1), 'Babam vefat etti, mirası paylaşırken kardeşlerim bana en küçük payı verdi çünkü sen zaten iyi kazanıyorsun dediler. İtiraz etmedim ama içim parçalandı. Para değil, değer görmemek koydu. Şimdi onlarla konuşmuyorum, haklı mıyım?', true, 'Aile', 'Aile', 4013, 4, 'approved', now() - interval '5199 minutes'),
  ('210953b7-8e26-4d4b-a89d-f4e5678c1b6d', (select id from public.profiles order by random() limit 1), 'Çocuğum bebekken çok zor günler geçirdim, ona yeterince ilgi gösteremedim. Şimdi o büyüdü ve bana mesafeli. Telafi etmeye çalışıyorum ama o duvarı aşamıyorum. Keşke o zamanlar daha güçlü olabilseymişim. Bu pişmanlık beni içten içe yiyor.', true, 'Pişmanlık', 'Pişmanlık', 1118, 4, 'approved', now() - interval '9262 minutes'),
  ('afd1464c-c41e-40b0-9b18-d484674de3d9', (select id from public.profiles order by random() limit 1), 'Kayınvalidem benimle aynı evde yaşıyor ve eşim hep onun tarafını tutuyor. Kendi evimde misafir gibiyim. Geçen gün ya annem ya ben demek üzereydim ama korktum. Sessiz kalmaya devam mı etmeliyim, yoksa bu evi bırakıp gitmeli miyim?', true, 'Dram', 'Dram', 178, 4, 'approved', now() - interval '5324 minutes'),
  ('816b5192-4e05-4e97-88dc-a331245bdbb7', (select id from public.profiles order by random() limit 1), 'Toplu taşımada yaşlı bir teyze düştü, herkes baktı ama kimse kalkmadı, ben de. Sonra biri yardım etti. O an neden donup kaldığımı hâlâ anlamıyorum. Eve gelince utancımdan ağladım. Bazen insanın en kötü yanı en beklenmedik anda çıkıyor.', true, 'Utanç', 'Utanç', 87, 4, 'approved', now() - interval '11978 minutes'),
  ('101cf447-0f8a-4376-8384-924964245a8f', (select id from public.profiles order by random() limit 1), 'Görücü usulü evlendim, eşimi tanımadan. İlk yıl çok zorlandım ama şimdi onsuz bir hayat düşünemiyorum. Komik olan, çocukken asla görücü usulü evlenmem derdim. Bazen en güzel şeyler en beklemediğin yerden geliyormuş. İtirafım bu, mutluyum.', true, 'Aşk', 'Aşk', 5776, 3, 'approved', now() - interval '13540 minutes'),
  ('344aa41d-4a21-4214-aa4c-bdfd71b75bf6', (select id from public.profiles order by random() limit 1), 'Üniversitede bitirme projemi internetten bulup kendiminmiş gibi sundum, kimse fark etmedi, yüksek not aldım. Şimdi o alanda çalışıyorum ama her toplantıda ya yakalanırsam diye içim titriyor. Bir yalanın üstüne koca bir kariyer kurdum.', true, 'Okul', 'Okul', 1021, 5, 'approved', now() - interval '1298 minutes'),
  ('75064cad-89e3-41fc-91cb-ae500fdbd8bc', (select id from public.profiles order by random() limit 1), 'Eşim beni aldattı, öğrendim ama affettim çünkü çocuklarımız var. Herkese mutluyuz diyorum, sosyal medyada poz veriyoruz. Ama içimde o güven bir daha asla geri gelmedi. Her gece yanımda yatarken bir yabancıyla uyuyormuşum gibi hissediyorum.', true, 'Aldatma', 'Aldatma', 566, 5, 'approved', now() - interval '22296 minutes'),
  ('5c87ee28-5d05-40b0-b027-36f6848cd165', (select id from public.profiles order by random() limit 1), 'Yıllar önce kaybettiğim bir cüzdanı bulan biri içindeki tüm parayla beraber geri getirmişti. O gün insanlığa olan inancım tazelendi. Şimdi ben de bulduğum her şeyi sahibine ulaştırıyorum. Küçük bir iyilik bir ömrü değiştirebiliyormuş.', true, 'Diğer', 'Diğer', 1847, 2, 'approved', now() - interval '12652 minutes'),
  ('d7fe0e0f-b66f-434e-9a6c-686fd93636a4', (select id from public.profiles order by random() limit 1), 'Eşim kumar oynuyor ve ailemizin tüm birikimini bitirdi. Annesi babası bilmiyor, ben örtbas ediyorum çünkü utanıyorum. Çocuklarımın geleceği için bir kenara koyduğum parayı da aldı. Onu seviyorum ama artık nefes alamıyorum. Bu evi nasıl kurtarırım?', true, 'Dram', 'Dram', 4705, 3, 'approved', now() - interval '11964 minutes'),
  ('7f50da8d-81ee-4bd0-b697-d169eff61e4e', (select id from public.profiles order by random() limit 1), 'Kız kardeşim benden habersiz nişanlımla mesajlaşıyormuş. Telefonunu görünce dünyam yıkıldı. Anneme söylesem aile dağılır, söylemesem bu ihanetle nasıl yaşarım? İkisi de bana en yakın iki insan. Şu an kime güveneceğimi bilmiyorum.', true, 'Aile', 'Aile', 727, 5, 'approved', now() - interval '10718 minutes'),
  ('d7da63e7-1096-48f2-aa72-1fa1d41106cd', (select id from public.profiles order by random() limit 1), 'Babama hayatımda hiç seni seviyorum diyemedim, hep gururuma yedirdim. Geçen ay aniden vefat etti. Şimdi mezarının başında saatlerce o cümleyi söylüyorum ama artık duyamıyor. Sevdiklerinize söyleyin, geç kalmayın. En büyük pişmanlığım bu.', true, 'Pişmanlık', 'Pişmanlık', 638, 6, 'approved', now() - interval '21483 minutes'),
  ('68ee3855-6b4d-438a-93ae-ade88e67a944', (select id from public.profiles order by random() limit 1), 'Eşim çok kıskanç, telefonumu, nereye gittiğimi sürekli kontrol ediyor. Başta beni seviyor diyordum ama artık nefes alamıyorum. Ayrılmak istesem sensiz yaşayamam diye tehdit ediyor. Korkuyorum, ne yapacağımı bilmiyorum. Bana bir yol gösterin.', true, 'Korku', 'Korku', 248, 3, 'approved', now() - interval '830 minutes'),
  ('0ab851bb-8ede-4efd-826b-282be4a7af4d', (select id from public.profiles order by random() limit 1), 'İnternetten tanıştığım biriyle iki yıldır yazışıyoruz, hiç görüşmedik ama onu çok seviyorum. Ailem tanımadığın biriyle olur mu diyor. Yarın ilk defa buluşacağız ve ödüm kopuyor. Ya hayal ettiğim gibi değilse? Yine de denemeye değer mi sizce?', true, 'Aşk', 'Aşk', 758, 5, 'approved', now() - interval '16229 minutes'),
  ('c1877b8a-9a97-4054-bcb3-c29239323c12', (select id from public.profiles order by random() limit 1), 'Patronum maaşları sürekli geciktiriyor ama kendine her ay yeni araba alıyor. Bir gün dayanamayıp ekibe gerçekleri anlattım, toplu istifa ettik. Şimdi işsizim ama vicdanım rahat. Bazen doğru olan en zor olandır. Pişman değilim, sadece korkuyorum.', true, 'İş Hayatı', 'İş Hayatı', 2997, 5, 'approved', now() - interval '4399 minutes'),
  ('70b1fb7e-6726-42da-89be-3b3a95c87c8d', (select id from public.profiles order by random() limit 1), 'Arkadaş grubunda hep ben dalga konusu olurum, gülüp geçiyorum ama içten içe çok kırılıyorum. Geçen gün ben de birine aynısını yaptım, sonra fark ettim ki ona acı çektirdim. Demek ki kırgınlık insanı kötü yapıyor. Özür diledim ama içim hâlâ rahat değil.', true, 'Utanç', 'Utanç', 289, 4, 'approved', now() - interval '14443 minutes'),
  ('892b2afe-75c8-43e6-8384-9e2873f5c652', (select id from public.profiles order by random() limit 1), 'Annem ölmeden önce bana bir sır verdi: ağabeyim aslında üvey kardeşimmiş. Bunu kimse bilmiyor, ağabeyim de. Şimdi ona her baktığımda bu sır boğazıma düğümleniyor. Söylesem ailemiz sarsılır, söylemesem bu yükü tek başıma taşıyacağım. Ne yapmalıyım?', true, 'Aile', 'Aile', 2246, 3, 'approved', now() - interval '2134 minutes'),
  ('76b76510-b8e2-4482-af71-7c37076c7ea1', (select id from public.profiles order by random() limit 1), 'Eşim işsiz kaldı, ben çalışıyorum ama evin tüm yükü bende. Bunu hiç yüzüne vurmadım ama o gururundan bana karşı soğudu. Yardım etmek istiyorum ama o reddediyor. İkimiz de mutsuzuz. Sevgi yetmiyor mu gerçekten, anlamıyorum.', true, 'Dram', 'Dram', 4892, 2, 'approved', now() - interval '18894 minutes'),
  ('fc63b5e4-e920-4e84-976a-60489b970b77', (select id from public.profiles order by random() limit 1), 'Lise aşkımla evlenecektik ama ben kariyerim için başka şehre gittim, ilişki bitti. Şimdi çok başarılıyım ama her gece yalnız uyuyorum. O ise mutlu bir aile kurmuş. Başarı geldi ama mutluluk gitti. Doğru seçim miydi, hâlâ bilmiyorum.', true, 'Pişmanlık', 'Pişmanlık', 5923, 5, 'approved', now() - interval '17666 minutes'),
  ('f7ff0ed4-b6a6-49ab-ab20-7d6f06917494', (select id from public.profiles order by random() limit 1), 'Eşimin telefonunda eski sevgilisiyle yıllardır devam eden bir yazışma buldum. Fiziksel bir şey yok ama duygusal olarak ona bağlı. Bunu söylesem sadece arkadaşız diyecek. Aldatma sadece fiziksel mi olur, yoksa kalbin başkasında olması da aldatmak mı?', true, 'Aldatma', 'Aldatma', 4924, 6, 'approved', now() - interval '21755 minutes'),
  ('7d458a25-ee71-452a-9407-dd3c487422e5', (select id from public.profiles order by random() limit 1), 'Çocuğum okulda sürekli sorun çıkarıyor, öğretmen beni çağırdı. Meğer evdeki tartışmalarımızdan etkileniyormuş. Eşimle çocuğun önünde kavga etmeyelim dedik ama beceremiyoruz. En çok onu üzdüğümüz için kendimi affedemiyorum. Nasıl düzeltebilirim?', true, 'Aile', 'Aile', 128, 5, 'approved', now() - interval '665 minutes'),
  ('47e3d083-6eb0-4097-9ade-cdeb4020da85', (select id from public.profiles order by random() limit 1), 'Komşum sürekli kapımı çalıp eşin yok mu yalnız mısın diye soruyor, bana garip bakıyor. Eşime söyledim, abartma dedi. Ama ben tedirginim, evde yalnızken korkuyorum. Taşınmak mı doğru, yoksa kuruntu mu yapıyorum? Kafam çok karışık.', true, 'Korku', 'Korku', 1955, 3, 'approved', now() - interval '15268 minutes'),
  ('451e9894-cbf0-40fa-823a-e2aaed5ef46c', (select id from public.profiles order by random() limit 1), '20 yıldır aynı kurumda çalışıyorum, emekliliğime az kaldı. Yeni gelen genç yönetici beni verimsiz diye işten çıkarmak istiyor. Onurum kırıldı. Bir ömür verdim bu işe. Sessizce gitmek mi, yoksa hakkımı sonuna kadar aramak mı, karar veremiyorum.', true, 'İş Hayatı', 'İş Hayatı', 2942, 6, 'approved', now() - interval '871 minutes'),
  ('d4461fb6-1e00-4da4-8ea8-672fdf6b4a80', (select id from public.profiles order by random() limit 1), 'Zor günümde bir arkadaşımdan borç istedim, vermedi. Sonra durumum düzeldi, o bana muhtaç oldu, ben de vermedim. İntikam aldım ama hiç tatmin olmadım, sadece daha boş hissettim. Kötülük kötülüğü besliyormuş. Keşke ben daha iyi biri olsaymışım.', true, 'Utanç', 'Utanç', 1511, 6, 'approved', now() - interval '14067 minutes'),
  ('3d88009d-302e-4462-9691-e42fd59f95df', (select id from public.profiles order by random() limit 1), 'Eşimle 15 yıldır evliyiz, tutkulu bir aşk değil ama derin bir dostluk var aramızda. Bazen büyük aşkı kaçırdım mı diye düşünüyorum. Ama o hastayken başucumda bekleyince anladım ki gerçek sevgi buymuş. Filmlerdeki gibi değil ama bizimki gerçek.', true, 'Aşk', 'Aşk', 2132, 4, 'approved', now() - interval '20212 minutes'),
  ('f166a38c-8d4c-48ee-998a-dfda9c156e0f', (select id from public.profiles order by random() limit 1), 'Sokakta gördüğüm bir köpeği eve aldım, hayatım değişti. En kötü günümde tek tesellim o oldu. İnsanlar beni yargıladı sorumluluk diye ama o bana koşulsuz sevgiyi öğretti. Bazen en sadık dostlar dört ayaklı oluyor. İtirafım: onsuz bir hayat düşünemiyorum.', true, 'Diğer', 'Diğer', 1967, 6, 'approved', now() - interval '21925 minutes'),
  ('06195c1c-a61f-4019-8e86-a9e6b1f579d8', (select id from public.profiles order by random() limit 1), 'Anneme yıllarca sen beni anlamıyorsun diye kızdım, kapısını yüzüne kapattım. Şimdi ben anne oldum ve onun ne kadar fedakârlık yaptığını anlıyorum. Telefonu açıp özür dilemek istiyorum ama gururum izin vermiyor. Bu inadı kırmak neden bu kadar zor?', true, 'Pişmanlık', 'Pişmanlık', 2850, 3, 'approved', now() - interval '13347 minutes'),
  ('313542d2-6557-4bc6-b273-ae6eb8215590', (select id from public.profiles order by random() limit 1), 'Eşim çok borçlandı, alacaklılar kapıya dayandı. Ben habersizdim, evi satmak zorunda kaldık. Çocuklarım kendi odalarından oldu. Ona kızgınım ama bırakıp gidemiyorum çünkü ona ihtiyacım var, o da bana. Sıfırdan başlamak mümkün mü gerçekten?', true, 'Dram', 'Dram', 753, 3, 'approved', now() - interval '10063 minutes'),
  ('1af186cc-7978-49b1-8c8b-5ece1509234d', (select id from public.profiles order by random() limit 1), 'Bekarlığa veda gecemde bir hata yaptım, düğünden bir hafta önce. Eşim asla bilmiyor, çok mutlu evliyiz. Ama her yıldönümümüzde o gece aklıma geliyor ve gülümsemem kayboluyor. Bu sırrı taşımak bir ömür sürecek. Söylemek doğru mu, yoksa korumak mı?', true, 'Aldatma', 'Aldatma', 302, 3, 'approved', now() - interval '3983 minutes');
